    .otter-button-secondary:hover, .otter-btn-secondary:hover {
      background-color: #475569;
    }
    .otter-button-danger, .otter-btn-danger {
      background-color: #dc2626;
      color: #ffffff;
      border: none;
      border-radius: 8px;
      padding: 10px 18px;
      font-weight: 600;
      cursor: pointer;
